import { get, post } from '@helpers/httpClient';

import { mapHikingMenuSaveToFront } from '../@mappers/hikingSaves.mapper';
import { IHikingMenuSaveDTO } from '../@types/hiking.backendTypes';
import { IHikingMenuSave } from '../@types/hiking.baseTypes';

export const getHikingMenuSavesAsync = async (id_hiking: number): Promise<IHikingMenuSave[]> => {
  const res = await get<IHikingMenuSaveDTO[], { id_hiking: number }>(
    '/ajax/hiking/menu/saves_list.php',
    { id_hiking },
  );
  return res.map(mapHikingMenuSaveToFront);
};

export const applyHikingMenuSaveAsync = async (
  id_hiking: number,
  id: number,
): Promise<{ success?: boolean; error?: string }> => {
  const res = await post<{ success?: boolean; error?: string }>(
    '/ajax/hiking/menu/saves_apply.php',
    { id, id_hiking },
  );
  return res;
};

export const saveHikingMenuSaveAsync = async (
  id_hiking: number,
  name: string,
): Promise<{ id?: number; success?: boolean; error?: string }> => {
  const res = post('/ajax/hiking/menu/saves_save.php', { id_hiking, name });
  return res;
};
export const renameHikingMenuSaveAsync = async (
  id_hiking: number,
  id: number,
  name: string,
): Promise<{ id?: number; success?: boolean; error?: string }> => {
  const res = post('/ajax/hiking/menu/saves_rename.php', { id, id_hiking, name });
  return res;
};
export const deleteHikingMenuSaveAsync = async (
  id_hiking: number,
  id: number,
): Promise<{ success?: boolean; error?: string }> => {
  const res = await post<{ success?: boolean; error?: string }>('/ajax/hiking/menu/saves_del.php', {
    id,
    id_hiking,
  });
  return res;
};

export const confirmHikingMenuSaveAsync = async (
  id_hiking: number,
  id: number,
  confirm: boolean,
): Promise<{ success?: boolean; error?: string }> => {
  const res = await post<{ success?: boolean; error?: string }>(
    '/ajax/hiking/menu/saves_confirm.php',
    { id, id_hiking, confirm },
  );
  return res;
};
